<?php require_once('dbstring.php');require_once('website-content-utils.php');aps_website_ensure($con);$rows=mysqli_query($con,"SELECT title,announcement_text,published_at FROM tblwebsiteannouncements WHERE status='published' ORDER BY published_at DESC");?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>School Announcements | Awuah Preparatory School</title><style>body{margin:0;background:#f3f7fa;color:#183650;font:16px/1.6 Arial}.wrap{max-width:850px;margin:45px auto;padding:0 20px}a{color:#08766f;font-weight:bold}.entry{background:#fff;border:1px solid #d7e2ea;border-radius:12px;padding:24px;margin:16px 0}.entry h2{margin:4px 0 10px;font-family:Georgia}.date{color:#08766f;font-size:13px;font-weight:bold}.entry p{white-space:pre-line}.empty{padding:30px;background:#fff;border-radius:12px}</style></head><body><main class="wrap"><a href="website.php">← Awuah Preparatory School</a><h1>School announcements</h1><?php if(!$rows||!mysqli_num_rows($rows)){?><p class="empty">There are no announcements at the moment.</p><?php }while($row=mysqli_fetch_assoc($rows)){?><article class="entry"><span class="date"><?php echo aps_website_escape(date('d F Y',strtotime($row['published_at'])));?></span><h2><?php echo aps_website_escape($row['title']);?></h2><p><?php echo aps_website_escape($row['announcement_text']);?></p></article><?php }?></main></body></html>
